```javascript
const fs = require('fs');

// --- CONFIGURAÇÕES E ARQUIVOS ---
const CAMINHO_RELACAO = './relacionamentos.json';
const CAMINHO_AKINTOR = './aki.json';

/**
 * Inicializa ou lê o arquivo de relacionamentos com segurança.
 */
function initRelacaoDados() {
    try {
        if (!fs.existsSync(CAMINHO_RELACAO)) {
            console.log(`Criando ${CAMINHO_RELACAO}...`);
            fs.writeFileSync(CAMINHO_RELACAO, JSON.stringify({ casamentos: [], namoros: [] }, null, 2));
        } else {
            const data = JSON.parse(fs.readFileSync(CAMINHO_RELACAO, 'utf-8'));
            // Garante a estrutura correta se estiver vazia/incompleta
            if (!data.casamentos || !data.namoros) {
                data.casamentos = [];
                data.namoros = [];
                fs.writeFileSync(CAMINHO_RELACAO, JSON.stringify(data, null, 2));
            }
        }
        return JSON.parse(fs.readFileSync(CAMINHO_RELACAO, 'utf-8'));
    } catch (erro) {
        console.error("Erro ao ler arquivo de relacionamentos:", erro.message);
        return { casamentos: [], namoros: [] };
    }
}

/**
