        "LEPRECHAUN RICHES": { min: 0.93, media: 3.59, max: 7.91, chance: 38 },
        // Outros jogos aqui...
    };
    */
    return akiData; 
}

// --- FUNÇÕES AUXILIARES ---

/**
 * Simula variação nas porcentagens e valores para gerar estatísticas dinâmicas.
 * Adiciona pequena aleatoriedade entre ±10% e garante chance mínima de 1%.
 */
function atualizarValores(dadosBase) {
    return {
        min: Math.round(dadosBase.min * (1 + (Math.random() * 0.2 - 0.1)) * 100) / 100,
        media: Math.round(dadosBase.media * (1 + (Math.random() * 0.2 - 0.1)) * 100) / 100,
        max: Math.round(dadosBase.max * (1 + (Math.random() * 0.2 - 0.1)) * 100) / 100,
        chance: Math.max(1, Math.min(100, Math.round(dadosBase.chance + (Math.floor(Math.random() * 10 - 5))))
    };
}

/**
 * Formata os dados em uma string estilo Markdown.
 * @param {string} nomeJogo - Nome do jogo sendo exibido.
 * @param {Object} dadosEstadisticas - Objeto resultante de atualizarValores.
 * @returns {string} Texto formatado pronto para retorno.
 */
function gerarRelatorio(nomeJogo, dadosEstadisticas) {
    return `🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n` +
           `*❲${nomeJogo}❳*\n` +
           `• *Mínimo:* R$ ${dadosEstadisticas.min.toFixed(2)}\n` +
           `• *Média:*  R$ ${dadosEstadisticas.media.toFixed(2)}\n` +
           `• *Máximo:* R$ ${dadosEstadisticas.max.toFixed(2)}\n` +
           `• *Chance:* ${dadosEstadisticas.chance}%\n\n` +
           `Observação: As porcentagens podem conter alguma divergência...`;
}

// --- LÓGICA PRINCIPAL DA RESPOSTA ---

export default async (jogo, relacoes) => {
    const dadosBaseJogos = initJogosDados();
    const dadosRelacoes = initRelacaoDados(); // Utilizei para garantir existência, embora pareça irrelevante para a lógica de jogos

    // Tratamento especial para opção 'all' (todas as opções)
    if (jogo === 'all') {
        let resumo = "🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n";

        // Verifica se existe o objeto jogos antes de iterar
        Object.keys(dadosBaseJogos).forEach((nome) => {
            if (dadosBaseJogos[nome]) {
                const atualizados = atualizarValores(dadosBaseJogos[nome]);
                resumo += gerarRelatorio(nome, atualizados);
            }
        });

        return resumo.trim();
    }

    // Busca dados específicos para o jogo solicitado
    const jogoDestino = dadosBaseJogos[jogo];

    if (!jogoDestino) {
        return `❌ Jogo "${jogo}" não encontrado.`;
    }

    const dadosAtualizados = atualizarValores(jogoDestino);

    return gerarRelatorio(jogo, dadosAtualizados);
};
```

### Principais Alterações Realizadas:

1.  **Definição de Módulos**: Removi variáveis globais desnecessárias (`const casamento_json = './...';`) e coloquei dentro de funções auxiliares (`initRelacaoDados`, `initJogosDados`). Isso evita poluição global e permite importar apenas o necessário.
2.  **Função de Formatação**: Criei uma função dedicada `gerarRelatorio`. Evita repetição de strings (`concatenação`) e torna fácil alterar o layout visual do relatório.
3.  **Segurança nos JSON**: Implementei verificação explícita de `fs.existsSync` e tratamento de erros ao fazer `JSON.parse`.
4.  **Lógica de `all`**: Reforcei a verificação de que o jogo existe na lista antes de tentar atualizar seus valores (evitamos índices inválidos ou acesso indevido).
5.  **Tipagem Numérica**: Forçando números de volta ao formato correto (ex: arredondamento dos preços reais) para evitar comportamentos inesperados com `toFixed` em nulos ou NaN.

